import{z as B,x as A,o as E,c as d,q as i,j as l,D as t,d as o,s as n,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"Web 竞态","description":"","frontmatter":{"title":"Web 竞态","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/web-race-condition.md","filePath":"cs/web-race-condition.md","lastUpdated":1791063341000}'),p={name:"cs/web-race-condition.md"};function c(D,a,h,m,b,u){const r=A("Mermaid");return E(),d("div",null,[a[2]||(a[2]=i('<h1 id="web-竞态" tabindex="-1">Web 竞态 <a class="header-anchor" href="#web-竞态" aria-label="Permalink to &quot;Web 竞态&quot;">​</a></h1><div class="epigraph"><p>检查与使用若中间插入另一请求，优惠券、余额、一次性令牌就会被用两次。Web 的并发是多请求，不是只线程库。防御是原子更新与幂等键。</p><footer>—— 据 CWE-362；对照[TOCTOU](/cs/toctou)</footer></div><p>上一课<a href="/cs/xxe">XXE</a>的病根在解析器；本课缺口是<strong>时间</strong>：主干 TOCTOU 课已给文件系统的竞态，这里落到 HTTP 请求处理。不给刷余额的操作指导。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>典型形态：处理「扣 100 元」的代码先读余额、判断充足、再写回——两个并发请求都在对方写入前完成读取，一次扣款被执行两次或提现两次。一次性令牌同理：「检查用过没有」与「标记已用」是两条语句，中间就是窗口。缺口是三件：数据库层约束（CHECK、唯一索引）、行锁或条件更新（UPDATE ... WHERE balance &gt;= 100）、幂等键让重试不产生第二次效果。</p><h3 id="最终一致" tabindex="-1">最终一致 <a class="header-anchor" href="#最终一致" aria-label="Permalink to &quot;最终一致&quot;">​</a></h3><p>跨服务没有分布式事务时，竞态窗口以秒计：只能靠幂等键加异步对账兜底，不能靠应用层的先后判断。</p><p><span class="marginnote">CWE-362。禁止利用竞态的步骤。业务逻辑下一课更广。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是把判断压进原子操作：余额用单条条件更新，令牌用表上唯一约束让第二次插入直接失败，支付接口以幂等键去重。设计口号是「不变量交给存储引擎」，应用层代码不再自查并发。下一课业务逻辑漏洞：授权与工作流。</p><p><span class="marginnote">直觉类比：两个收银员同时看同一本账簿的同一页——各自看到「够扣」就各自记账，账就记重了；唯一约束相当于让账簿自己拒绝把第二笔记在同一编号上，谁后写谁失败。</span></p>',12)),(E(),l(s,null,{default:t(()=>[n(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20CHK%5B%22%E6%A3%80%E6%9F%A5%22%5D%20--%3E%20GAP%5B%22%E5%8F%A6%E4%B8%80%E8%AF%B7%E6%B1%82%E6%8F%92%E5%85%A5%22%5D%0A%20%20GAP%20--%3E%20USE%5B%22%E4%BD%BF%E7%94%A8%22%5D%0A%20%20ATOM%5B%22%E5%8E%9F%E5%AD%90%E6%9B%B4%E6%96%B0%E6%88%96%E5%94%AF%E4%B8%80%E7%BA%A6%E6%9D%9F%22%5D%20--%3E%20OK%5B%22%E4%B8%8D%E8%83%BD%E5%8F%8C%E8%8A%B1%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"机制定位在 CIA 的 I：每条不变量（余额非负、令牌一次性）在串行下成立，并发下检查与使用的间隙被另一请求插入，不变量即破。注意 Web 的并发单位是并行请求——用户双击、脚本重放、弱网重试都会自然产生并发，不需要专门工具。业务逻辑下一课：有些错即使单线程也会犯。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"数字实例：余额 150 元，两个并发「扣 100」请求都读到 150、都判定够、都写回 50——串行正确结果应是一笔成功余额 50、另一笔被拒；竞态下两笔都成功且写回同一个 50，窗口就开在「判断」与「写回」之间。")],-1)),(E(),l(s,null,{default:t(()=>[n(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E8%AF%B7%E6%B1%82A%EF%BC%9A%E8%AF%BB%E4%BD%99%E9%A2%9D%20150%22%5D%20--%3E%20B%5B%22%E8%AF%B7%E6%B1%82A%EF%BC%9A%E5%88%A4%E6%96%AD%20150%E2%89%A5100%22%5D%0A%20%20C%5B%22%E8%AF%B7%E6%B1%82B%EF%BC%9A%E8%AF%BB%E4%BD%99%E9%A2%9D%20150%22%5D%20--%3E%20D%5B%22%E8%AF%B7%E6%B1%82B%EF%BC%9A%E5%88%A4%E6%96%AD%20150%E2%89%A5100%22%5D%0A%20%20B%20--%3E%20E%5B%22A%20%E5%86%99%E5%9B%9E%2050%22%5D%0A%20%20D%20--%3E%20F%5B%22B%20%E5%86%99%E5%9B%9E%2050%22%5D%0A%20%20E%20--%3E%20R%5B%22%E4%B8%A4%E7%AC%94%E9%83%BD%E7%94%9F%E6%95%88%EF%BC%8C%E4%BD%99%E9%A2%9D%E4%BB%8D%E6%98%AF%2050%22%5D%0A%20%20F%20--%3E%20R%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写并发 PoC；边界要点名：分布式锁不是银弹——锁超时与锁服务自身的竞态都要进设计，最稳的锚是数据库约束这类绕不过的层。业务逻辑漏洞下一课。</p><p><span class="marginnote">常见误区：以为加了分布式锁就安全——锁有超时，持锁方一旦卡顿超时被强制释放，第二个请求就能拿到锁把同一段逻辑再跑一遍；锁只是缩小窗口，存储层约束才是绕不过的底线。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>XXE 是解析；竞态是检查与使用的间隙。</li><li>原子约束优于应用层判断。</li><li>Web 并发等于并行请求。</li><li>下一课业务逻辑。</li><li>出处：CWE-362；<a href="/cs/toctou">toctou</a>。</li></ul>',5))])}const F=B(p,[["render",c]]);export{f as __pageData,F as default};
